mapper.select:
SELECT COALESCE(SUM(e.amount), 0)
FROM expenses e
WHERE e.user_id = #{userId}
    AND (
            (
                e.expense_date >= #{monthStart}
                AND e.expense_date < #{nextMonthStart}
            )
            OR
            (
                e.expense_date IS NULL
                AND e.created_at >= #{createdAtStart}
                AND e.created_at < #{createdAtEnd}
            )
    )

SELECT COALESCE(SUM(e.amount), 0)
FROM expenses e
WHERE e.user_id = #{userId}
    AND e.expense_date = #{today}

mapper.update:
UPDATE expenses
SET
    amount = #{expense.amount},
    category_id = #{expense.categoryId},
    memo = #{expense.memo},
    expense_date = #{expense.expenseDate},
    expense_time = #{expense.expenseTime}
WHERE id = #{expense.id}
    AND user_id = #{userId}

mapper.delete:
DELETE FROM expenses
WHERE id = #{id}
    AND user_id = #{userId}
